// Authored teaching spectra, not planetary observations or mineral identifications.
export function sampleSpectrum(site){return Array.from({length:41},(_,i)=>{const wavelength=.8+i*.04,depth=[.15,.35,.22][site];return{wavelength:+wavelength.toFixed(2),reflectance:+(.72-depth*Math.exp(-(((wavelength-1.5)/.095)**2))-.13*Math.exp(-(((wavelength-2)/.14)**2))).toFixed(4)};});}
export function observationMarkup(r){
 if(r.objective!=='composition'||r.scans!==3)return '';
 const colors=['#91edcb','#ffd18c','#c7acff'],lines=r.nodes.map((n,i)=>`<polyline fill="none" stroke="${colors[i]}" stroke-width="3" points="${(n.spectrum||[]).map(p=>(45+(p.wavelength-.8)/1.6*510).toFixed(1)+','+(180-p.reflectance*160).toFixed(1)).join(' ')}"/>`).join('');
 return `<section class="flight-evidence"><h2>Read your spectra</h2><p>Synthetic teaching data, not NASA observations. Lower reflectance at a wavelength means less light returned there.</p><svg viewBox="0 0 600 225" role="img" aria-label="Comparison of three synthetic reflectance spectra"><path d="M45 20V180H555" stroke="#63818c" fill="none"/>${lines}<g fill="#b9c9ce" font-size="12"><text x="12" y="26">1.0</text><text x="12" y="184">0.0</text><text x="45" y="200">0.8</text><text x="260" y="200">1.5</text><text x="535" y="200">2.4 μm</text></g></svg><div class="evidence-key" data-no-translate><span style="color:${colors[0]}">■ 01</span><span style="color:${colors[1]}">■ 02</span><span style="color:${colors[2]}">■ 03</span></div><p>Which site has the deepest dip near 1.5 μm?</p><div class="buttons">${[1,2,3].map(i=>`<button class="secondary" data-spectrum-answer="${i}" aria-label="SITE ${i}">0${i}</button>`).join('')}</div><p id="spectrum-feedback" role="status"></p><p class="story-note">These curves demonstrate spectral comparison. They do not establish a material or prove water is present.</p><a href="https://science.nasa.gov/learn/basics-of-space-flight/chapter12-1/" target="_blank" rel="noopener noreferrer">NASA / science instruments ↗</a></section>`;
}

